from pathlib import Path

import numpy as np
import pandas as pd


# ---------------------------------------------------------
# 1. Define robust paths based on the script location
# ---------------------------------------------------------
# Folder where this Python script is located:
# RAG-timing-attack/term_frequencies/
BASE_DIR = Path(__file__).resolve().parent

# Project root:
# RAG-timing-attack/
PROJECT_DIR = BASE_DIR.parent

# Input file with the PG19 noun frequencies
TERMS_PATH = BASE_DIR / "noun_frequencies_pg19.csv"

# Breakpoints generated by the segmented regression
BREAKPOINTS_PATH = (
    PROJECT_DIR
    / "frequency-distributions-both-experiments"
    / "frequency_regime_results"
    / "pg19_breakpoints.csv"
)

# Output file
OUTPUT_PATH = BASE_DIR / "pg19_terms_with_partitions.csv"


def assign_partitions(
    terms_path,
    breakpoints_path,
    output_path
):
    """
    Assign each term to a partition using the breakpoint ranks
    estimated by the segmented regression.

    The output contains:
        term, frequency, partition
    """

    # -----------------------------------------------------
    # 2. Check that the files exist
    # -----------------------------------------------------
    if not terms_path.exists():
        raise FileNotFoundError(
            f"Terms file not found:\n{terms_path}"
        )

    if not breakpoints_path.exists():
        raise FileNotFoundError(
            f"Breakpoints file not found:\n{breakpoints_path}"
        )

    # -----------------------------------------------------
    # 3. Load terms and breakpoints
    # -----------------------------------------------------
    terms = pd.read_csv(terms_path)
    breakpoints = pd.read_csv(breakpoints_path)

    # -----------------------------------------------------
    # 4. Validate and clean the term-frequency file
    # -----------------------------------------------------
    required_term_columns = {"term", "frequency"}

    missing_terms = required_term_columns - set(terms.columns)

    if missing_terms:
        raise ValueError(
            f"Missing columns in terms file: {missing_terms}. "
            f"Available columns: {list(terms.columns)}"
        )

    terms = terms.copy()

    terms["frequency"] = pd.to_numeric(
        terms["frequency"],
        errors="coerce"
    )

    terms = terms.dropna(
        subset=["term", "frequency"]
    )

    terms = terms[
        terms["frequency"] > 0
    ].copy()

    # -----------------------------------------------------
    # 5. Sort by frequency and create rank if necessary
    # -----------------------------------------------------
    # The rank must be generated exactly as in the segmented
    # regression: highest frequency first.
    terms = terms.sort_values(
        "frequency",
        ascending=False,
        kind="mergesort"
    ).reset_index(drop=True)

    terms["rank"] = np.arange(
        1,
        len(terms) + 1
    )

    # -----------------------------------------------------
    # 6. Validate the breakpoint file
    # -----------------------------------------------------
    if "rank" not in breakpoints.columns:
        raise ValueError(
            "The breakpoints file must contain a 'rank' column. "
            f"Available columns: {list(breakpoints.columns)}"
        )

    breakpoints["rank"] = pd.to_numeric(
        breakpoints["rank"],
        errors="coerce"
    )

    breakpoint_ranks = (
        breakpoints["rank"]
        .dropna()
        .astype(int)
        .sort_values()
        .unique()
        .tolist()
    )

    if not breakpoint_ranks:
        raise ValueError(
            "No valid breakpoint ranks were found."
        )

    # -----------------------------------------------------
    # 7. Build the partition intervals
    # -----------------------------------------------------
    # Example with five breakpoints:
    #
    # Partition 1: rank <= b1
    # Partition 2: b1 < rank <= b2
    # Partition 3: b2 < rank <= b3
    # Partition 4: b3 < rank <= b4
    # Partition 5: b4 < rank <= b5
    # Partition 6: rank > b5
    bins = [-np.inf] + breakpoint_ranks + [np.inf]

    partition_labels = list(
        range(1, len(breakpoint_ranks) + 2)
    )

    # -----------------------------------------------------
    # 8. Assign each term to its partition
    # -----------------------------------------------------
    terms["partition"] = pd.cut(
        terms["rank"],
        bins=bins,
        labels=partition_labels,
        right=True,
        include_lowest=True
    )

    terms["partition"] = terms[
        "partition"
    ].astype(int)

    # -----------------------------------------------------
    # 9. Keep only the requested columns
    # -----------------------------------------------------
    result = terms[
        [
            "term",
            "frequency",
            "partition"
        ]
    ].copy()

    # -----------------------------------------------------
    # 10. Save the output CSV
    # -----------------------------------------------------
    result.to_csv(
        output_path,
        index=False
    )

    # -----------------------------------------------------
    # 11. Print useful checks
    # -----------------------------------------------------
    print("\nProcess completed successfully.")
    print(f"Terms file:\n{terms_path}")
    print(f"\nBreakpoints file:\n{breakpoints_path}")
    print(f"\nOutput saved in:\n{output_path}")
    print(f"\nBreakpoints used: {breakpoint_ranks}")

    print("\nNumber of terms by partition:")
    print(
        result["partition"]
        .value_counts()
        .sort_index()
    )

    print("\nFirst classified terms:")
    print(result.head(10))

    return result


# ---------------------------------------------------------
# 12. Run the classification for Pg19
# ---------------------------------------------------------
pg19_classified = assign_partitions(
    terms_path=TERMS_PATH,
    breakpoints_path=BREAKPOINTS_PATH,
    output_path=OUTPUT_PATH
)